          </button>
          <div className="pb-3 text-xs text-white/40 sm:text-right">เรียง: {sortLabel()} · ทั้งหมด {posts.length.toLocaleString("th-TH")} โพสต์</div>
        </div>
        {notice ? <p role="status" className="mt-3 text-sm text-[#f4df9b]">{notice}</p> : null}
